{
  "missionStatement": "Conduct online research on room-temperature superconductivity and update the repository's key documents with new chemistry and physics insights for discovering and manufacturing room-temperature superconducting compounds.",
  "criteria": [
    {
      "description": "docs/online_research_summary.md is updated with a summary of at least 5 recent (2020+) papers on room-temperature superconductivity, including key findings, methods, and citations.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "literature_review.md is updated to incorporate new findings from the online research, with a section on recent advances in hydride, nickelate, and carbon-based superconductors.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "theoretical_framework.md includes a new section on the proposed mechanism for room-temperature superconductivity in the identified candidate materials, referencing the online research.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "candidate_materials.md is updated with at least 3 new candidate compounds, each listing composition, predicted Tc, synthesis route, and source reference from the online research.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "synthesis_methods.md includes detailed protocols for synthesizing the new candidate materials, covering high-pressure synthesis, doping, and other relevant techniques.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "characterization_techniques.md is updated to include methods for verifying room-temperature superconductivity in the new candidates, such as resistivity, magnetic susceptibility, and specific heat measurements.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "proposed_chemistry_physics.md is updated with a comprehensive proposal for discovering and manufacturing room-temperature superconducting compounds, integrating the online research findings and outlining key chemical and physical principles.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "discovery_strategy.md is updated to incorporate the new chemistry/physics insights and outlines a step-by-step plan for discovering and manufacturing room-temperature superconducting compounds.",
      "expectedFiles": ["discovery_strategy.md"]
    }
  ]
}

{
  "missionStatement": "Study superconducting materials via online research and propose chemistry and physics for discovering and manufacturing room-temperature superconducting compounds, updating existing documents and scripts with new insights.",
  "criteria": [
    {
      "description": "Online research summary document is updated with findings from at least three recent (2020+) papers on room-temperature superconductivity, including key mechanisms, materials, and challenges.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "Proposed chemistry and physics document is revised to incorporate new mechanisms (e.g., hydride, nickelate, carbon-based) and a unified framework for discovery and manufacturing.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Candidate materials list is updated with at least three new candidate compounds identified from online research, including predicted Tc and synthesis feasibility.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "Synthesis methods document is updated with detailed protocols for at least two new candidate material families (e.g., hydrides, nickelates) including high-pressure or thin-film techniques.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "Characterization techniques document is updated to include advanced methods (e.g., muon spin rotation, neutron scattering) relevant to verifying room-temperature superconductivity.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "Theoretical framework document is updated to incorporate new models (e.g., BCS-like, excitonic, or topological) that explain high-Tc in the proposed materials.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "Discovery strategy document is updated to include a systematic screening pipeline using online data and DFT calculations.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "Manufacturing scalability document is updated with a section on scale-up challenges and potential solutions for the proposed compounds.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Roadmap document is updated with new milestones and timelines reflecting the revised research direction.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "DFT calculator script is updated to support new material families (e.g., hydrides) and includes a function to compute Tc from electronic structure.",
      "expectedFiles": ["dft_calculator.py"]
    },
    {
      "description": "Pipeline script is updated to incorporate new candidate generation and Tc prediction modules from online research data.",
      "expectedFiles": ["run_pipeline.py"]
    },
    {
      "description": "All existing unit tests pass after changes, and at least one new test is added for the updated DFT calculator or pipeline.",
      "expectedFiles": ["tests/test_predict_tc.py", "tests/test_run_pipeline.py"]
    },
    {
      "description": "README is updated to reflect new documents and changes in the pipeline usage.",
      "expectedFiles": ["README.md"]
    }
  ]
}

